"src/services/VaultService.js": function(module, exports, __require, __externalRequire) {
const require = (request) => __require(request, "src/services/VaultService.js");
const { TFolder, TFile } = require("obsidian");

class VaultService {
  constructor(app) {
    this.app = app;
  }

  async ensureFolder(folderPath) {
    const parts = folderPath.split("/").filter(Boolean);
    let current = "";
    for (const part of parts) {
      current = current ? `${current}/${part}` : part;
      const existing = this.app.vault.getAbstractFileByPath(current);
      if (!existing) {
        await this.app.vault.createFolder(current);
      } else if (!(existing instanceof TFolder)) {
        throw new Error(`${current} exists but is not a folder.`);
      }
    }
  }

  getMarkdownFilesInFolder(folderPath) {
    const prefix = `${folderPath}/`;
    return this.app.vault.getMarkdownFiles()
      .filter((file) => file.path.startsWith(prefix))
      .sort((a, b) => {
        const byTime = (b.stat && b.stat.mtime || 0) - (a.stat && a.stat.mtime || 0);
        return byTime || a.basename.localeCompare(b.basename);
      });
  }

  async createUniqueNote(folderPath, baseName, content) {
    await this.ensureFolder(folderPath);
    let index = 1;
    while (true) {
      const name = `${baseName} ${index}.md`;
      const path = `${folderPath}/${name}`;
      if (!this.app.vault.getAbstractFileByPath(path)) {
        return this.app.vault.create(path, content);
      }
      index += 1;
    }
  }

  async appendToFile(file, content) {
    if (!(file instanceof TFile)) throw new Error("Target note is invalid.");
    await this.app.vault.append(file, content);
  }
}

module.exports = { VaultService };
},
"src/services/WorkspaceService.js": function(module, exports, __require, __externalRequire) {
const require = (request) => __require(request, "src/services/WorkspaceService.js");
class WorkspaceService {
  constructor(app) {
    this.app = app;
  }

  async openFile(file, mode) {
    if (!file || mode === "none") return;
    if (this.isFileOpen(file)) return;
    const leaf = this.getLeaf(mode);
    await leaf.openFile(file, { active: true });
  }

  isFileOpen(file) {
    if (!file) return false;
    return this.app.workspace.getLeavesOfType("markdown")
      .some((leaf) => leaf.view && leaf.view.file && leaf.view.file.path === file.path);
  }

  getLeaf(mode) {
    if (mode === "split") {
      try {
        const leaf = this.app.workspace.getLeaf("split", "vertical");
        if (leaf) return leaf;
      } catch (error) {
        return this.app.workspace.getLeaf(true);
      }
    }
    if (mode === "window") {
      if (this.app.workspace.openPopoutLeaf) {
        const leaf = this.app.workspace.openPopoutLeaf();
        if (leaf) return leaf;
      }
    }
    if (mode === "tab") {
      try {
        const leaf = this.app.workspace.getLeaf("tab");
        if (leaf) return leaf;
      } catch (error) {
        return this.app.workspace.getLeaf(true);
      }
    }
    return this.app.workspace.getLeaf(true);
  }
}

module.exports = { WorkspaceService };
},
